M = []

M.append({"id": "fond", "t": "Les fondamentaux de la conformité", "ic": "🏛️", "lvl": "Débutant",
 "intro": "Comprendre ce qu'est la conformité, le risque qu'elle gère et la place du compliance officer dans l'organisation.",
 "lessons": [
  {"t": "Définition et risque de non-conformité", "h": "<p>La <b>conformité</b> (compliance) est l'ensemble des dispositifs qui garantissent que l'établissement respecte les lois, règlements, normes professionnelles, règles déontologiques et procédures internes qui s'appliquent à ses activités.</p><p>Le <b>risque de non-conformité</b> est le risque de sanction judiciaire, administrative ou disciplinaire, de perte financière significative ou d'atteinte à la réputation, qui naît du non-respect de ces règles. C'est la définition posée par le Comité de Bâle dans son document de référence <i>« Compliance and the compliance function in banks »</i> (2005), reprise par les régulateurs du monde entier, dont ceux de l'UMOA.</p><p>Le risque de réputation est souvent le plus coûteux : une amende se paie, une perte de confiance des banques correspondantes ou des clients peut menacer la survie de l'établissement.</p>"},
  {"t": "Les principes du Comité de Bâle (2005)", "h": "<ul><li><b>Responsabilité de l'organe délibérant</b> (conseil d'administration) : il approuve la politique de conformité et en surveille l'application.</li><li><b>Responsabilité de la direction générale</b> : elle met en place une fonction conformité permanente et efficace.</li><li><b>Indépendance</b> : statut formel, responsable désigné, absence de conflit d'intérêts, accès à toute l'information et à tout le personnel.</li><li><b>Ressources</b> suffisantes et compétentes.</li><li><b>Missions</b> : conseiller, former, identifier et évaluer les risques, surveiller, tester, rendre compte.</li><li><b>Relation avec l'audit interne</b> : la conformité est elle-même soumise à l'audit périodique.</li></ul>"},
  {"t": "Le modèle des trois lignes", "h": "<p>Le modèle des <b>trois lignes</b> (révisé par l'IIA en 2020) organise la maîtrise des risques :</p><ul><li><b>1re ligne</b> : les métiers et opérations, qui prennent et gèrent les risques au quotidien (contrôles de premier niveau).</li><li><b>2e ligne</b> : les fonctions de support et de contrôle permanent, dont la <b>conformité</b> et la gestion des risques. Elles fixent le cadre, conseillent et surveillent.</li><li><b>3e ligne</b> : l'<b>audit interne</b>, qui donne une assurance indépendante sur l'ensemble.</li></ul><p>Le compliance officer est donc en 2e ligne : il ne fait pas le travail des métiers à leur place, il les outille et vérifie.</p>"},
  {"t": "Le rôle du compliance officer", "h": "<ul><li>Recenser les normes applicables et assurer la <b>veille réglementaire</b>.</li><li>Rédiger les politiques et procédures, donner des <b>avis de conformité</b> (nouveaux produits, opérations sensibles).</li><li>Construire la <b>cartographie des risques de non-conformité</b>.</li><li>Piloter le dispositif <b>LBC/FT/FP</b> et le filtrage des sanctions.</li><li><b>Former et sensibiliser</b> le personnel.</li><li>Contrôler, tester, suivre les plans d'action et <b>rendre compte</b> aux dirigeants, au conseil et au superviseur.</li></ul><p>Qualités clés : intégrité, courage de dire non, pédagogie, rigueur, sens des affaires.</p>"}],
 "key": ["Risque de non-conformité = sanctions + pertes + réputation", "Document de référence : Comité de Bâle 2005", "La conformité est une fonction de 2e ligne, indépendante", "Le conseil approuve la politique, la direction la met en œuvre"],
 "quiz": [
  Q("Quel organisme a publié en 2005 le document de référence « Compliance and the compliance function in banks » ?", ["Le GAFI", "Le Comité de Bâle sur le contrôle bancaire", "La BCEAO", "L'OCDE"], 1, "Le Comité de Bâle a fixé en 2005 les principes de la fonction conformité, repris par les superviseurs du monde entier."),
  Q("Dans le modèle des trois lignes, la conformité se situe :", ["En 1re ligne", "En 2e ligne", "En 3e ligne", "En dehors du modèle"], 1, "La conformité est une fonction de contrôle permanent de 2e ligne ; l'audit interne est la 3e ligne."),
  Q("Le risque de non-conformité comprend :", ["Uniquement le risque d'amende", "Le risque de sanction, de perte financière significative et d'atteinte à la réputation", "Uniquement le risque de crédit", "Le risque de marché"], 1, "C'est la définition de Bâle : sanctions, pertes et réputation."),
  Q("Qui approuve la politique de conformité d'une banque ?", ["Le responsable conformité", "L'auditeur externe", "L'organe délibérant (conseil d'administration)", "Le superviseur"], 2, "L'organe délibérant approuve la politique et en surveille l'application ; la direction générale la met en œuvre."),
  Q("Quelle condition N'est PAS une garantie d'indépendance de la conformité ?", ["Un accès libre à l'information", "Un responsable désigné", "Une rémunération liée aux résultats commerciaux du métier contrôlé", "Un accès direct aux dirigeants et au conseil"], 2, "Lier la rémunération aux résultats commerciaux crée un conflit d'intérêts incompatible avec l'indépendance."),
  Q("L'audit interne et la conformité :", ["Sont la même fonction", "Sont distinctes : l'audit évalue aussi l'efficacité de la conformité", "La conformité audite l'audit interne", "L'audit interne est en 2e ligne"], 1, "La conformité (2e ligne) est elle-même soumise à l'évaluation périodique de l'audit interne (3e ligne).")]})

M.append({"id": "umoa", "t": "Le cadre de la conformité dans l'UMOA et en Côte d'Ivoire", "ic": "🌍", "lvl": "Intermédiaire",
 "intro": "Les autorités, les textes et les exigences qui encadrent la fonction conformité des banques et établissements financiers de la zone UMOA.",
 "lessons": [
  {"t": "Les autorités", "h": "<ul><li><b>BCEAO</b> (Banque Centrale des États de l'Afrique de l'Ouest) : édicte les instructions applicables aux établissements (dont la LBC/FT/FP).</li><li><b>Commission bancaire de l'UMOA</b> : superviseur des établissements de crédit et compagnies financières ; son secrétariat général est installé à <b>Abidjan</b>. Elle édicte des circulaires et prononce des sanctions disciplinaires et pécuniaires.</li><li><b>AMF-UMOA</b> (ex-CREPMF) : régulateur du marché financier régional (BRVM, SGI, OPCVM).</li><li><b>CIMA</b> : régulateur des assurances (règlement LBC/FT/FP du 10 juillet 2025).</li><li><b>CENTIF</b> : cellule de renseignement financier nationale qui reçoit les déclarations de soupçon.</li><li><b>Ministère des Finances</b>, <b>PPEF</b> (Pôle pénal économique et financier) pour la répression.</li></ul>"},
  {"t": "Les circulaires de 2017 de la Commission bancaire", "h": "<p>Le 27 septembre 2017, la Commission bancaire a publié un socle de cinq circulaires :</p><ul><li><b>01-2017/CB/C</b> : gouvernance ;</li><li><b>02-2017/CB/C</b> : conditions d'exercice des fonctions d'administrateurs et de dirigeants ;</li><li><b>03-2017/CB/C</b> : contrôle interne ;</li><li><b>04-2017/CB/C</b> : gestion des risques ;</li><li><b>05-2017/CB/C</b> : <b>gestion de la conformité aux normes en vigueur</b>.</li></ul><p>La circulaire 05-2017 impose à la direction générale de mettre en place une <b>fonction conformité permanente</b> (article 5) et de désigner un <b>responsable</b> chargé de coordonner la gestion du risque de non-conformité (article 9).</p><p><b>Mise à jour 2026</b> : ces circulaires ont été actualisées en 2026, notamment par la circulaire n°011-04-2026 sur la gestion de la conformité. Les rôles des organes délibérant et exécutif restent globalement inchangés, mais le champ d'action de la conformité s'élargit. Vérifie toujours la dernière version sur cb-umoa.org.</p>"},
  {"t": "Les missions attendues par le superviseur", "h": "<ul><li>Recenser les normes en vigueur et tenir une base réglementaire à jour.</li><li>Identifier, évaluer et gérer le risque de non-conformité (cartographie).</li><li>Donner un avis préalable sur les nouveaux produits et activités.</li><li>Former et sensibiliser en permanence le personnel.</li><li>Contrôler le respect des règles et suivre les recommandations.</li><li>Rendre compte : rapports réguliers aux dirigeants, à l'organe délibérant et à la Commission bancaire.</li></ul>"},
  {"t": "Les sanctions de la Commission bancaire", "h": "<p>En cas de manquement, la Commission bancaire peut prononcer des <b>mesures administratives</b> (mise en garde, injonction, plan de retour à la conformité…), des <b>sanctions disciplinaires</b> (avertissement, blâme, jusqu'au retrait d'agrément) et des <b>sanctions pécuniaires</b>.</p><p>En 2025, elle a prononcé <b>trente blâmes</b>, dont deux à l'encontre d'institutions de microfinance, et <b>six avertissements</b>, presque tous assortis de sanctions pécuniaires. La conformité n'est pas un sujet théorique dans l'UMOA.</p>"}],
 "key": ["Commission bancaire : siège du secrétariat à Abidjan", "Circulaire 05-2017/CB/C = gestion de la conformité", "Fonction conformité permanente + responsable désigné", "Circulaires actualisées en 2026 (n°011-04-2026 pour la conformité)"],
 "quiz": [
  Q("Quelle circulaire de 2017 porte sur la gestion de la conformité aux normes en vigueur ?", ["01-2017/CB/C", "03-2017/CB/C", "04-2017/CB/C", "05-2017/CB/C"], 3, "La 05-2017/CB/C est entièrement consacrée à la conformité ; la 03 au contrôle interne, la 04 à la gestion des risques."),
  Q("Où est installé le secrétariat général de la Commission bancaire de l'UMOA ?", ["Dakar", "Abidjan", "Lomé", "Ouagadougou"], 1, "Le secrétariat général de la Commission bancaire est à Abidjan ; le siège de la BCEAO est à Dakar."),
  Q("Selon la circulaire 05-2017, qui doit mettre en place une fonction conformité permanente ?", ["L'auditeur externe", "L'organe exécutif (direction générale)", "La CENTIF", "Les actionnaires"], 1, "L'article 5 impose à l'organe exécutif de mettre en place une fonction conformité permanente."),
  Q("Quel régulateur encadre le marché financier régional de l'UMOA ?", ["La CIMA", "L'AMF-UMOA (ex-CREPMF)", "La CENTIF", "L'ARTCI"], 1, "L'AMF-UMOA, anciennement CREPMF, régule le marché financier régional (BRVM, SGI…)."),
  Q("Combien de blâmes la Commission bancaire a-t-elle prononcés en 2025 ?", ["Aucun", "Cinq", "Trente", "Cent"], 2, "Trente blâmes et six avertissements en 2025, presque tous assortis de sanctions pécuniaires."),
  Q("Quelle autorité régule les assurances en zone CIMA et a adopté un règlement LBC/FT/FP le 10 juillet 2025 ?", ["La CIMA", "La BCEAO", "La Commission bancaire", "Le GIABA"], 0, "La Conférence Interafricaine des Marchés d'Assurances (CIMA) encadre le secteur des assurances.")]})

M.append({"id": "lbc", "t": "LBC/FT/FP : le socle", "ic": "🛡️", "lvl": "Intermédiaire",
 "intro": "Blanchiment, financement du terrorisme et de la prolifération : définitions, textes, acteurs et actualité de la Côte d'Ivoire.",
 "lessons": [
  {"t": "Les trois étapes du blanchiment", "h": "<ol><li><b>Placement</b> : introduire les fonds illicites dans le système financier (dépôts d'espèces fractionnés, achats de biens…).</li><li><b>Empilement</b> (layering) : multiplier les opérations pour brouiller la trace (virements en cascade, sociétés écrans, juridictions opaques).</li><li><b>Intégration</b> : réinjecter les fonds dans l'économie légale avec une apparence licite (immobilier, investissements, faux prêts).</li></ol><p>Le <b>financement du terrorisme</b> peut utiliser de l'argent licite (petits montants, collectes, associations) : on cherche la <b>destination</b> des fonds, pas seulement leur origine. Le <b>financement de la prolifération</b> vise les armes de destruction massive (sanctions ciblées de l'ONU).</p>"},
  {"t": "Les textes dans l'UMOA et en Côte d'Ivoire", "h": "<ul><li><b>Loi uniforme relative à la LBC/FT/FP</b> adoptée par le Conseil des Ministres de l'UMOA le <b>31 mars 2023</b>, en réponse au 2e cycle d'évaluations mutuelles.</li><li>En Côte d'Ivoire, elle est transposée par l'<b>ordonnance n°2023-875 du 23 novembre 2023</b>, ratifiée en 2024. Elle abroge la loi n°2016-992 du 14 novembre 2016 et introduit notamment le <b>blanchiment autonome</b> (poursuivre le blanchiment sans devoir d'abord prouver l'infraction d'origine).</li><li><b>Ordonnance n°2022-237 du 30 mars 2022</b> : régime des sanctions administratives LBC/FT/FP et organisation du contrôle des assujettis (création d'une commission nationale des sanctions).</li><li><b>Instructions BCEAO du 18 mars 2025</b> : n°001-03-2025 (organisation, contrôle interne et conformité LBC/FT/FP, qui abroge l'instruction 007-09-2017), n°002-03-2025 (seuil des transports physiques intracommunautaires d'espèces), n°003-03-2025 (identification et connaissance de la clientèle).</li></ul>"},
  {"t": "Les acteurs", "h": "<ul><li><b>GAFI</b> : organisme intergouvernemental créé en 1989, auteur des <b>40 Recommandations</b> (révisées en 2012 et régulièrement mises à jour).</li><li><b>GIABA</b> : organisme régional de type GAFI pour l'Afrique de l'Ouest ; il conduit les évaluations mutuelles.</li><li><b>CENTIF-CI</b> : cellule de renseignement financier ivoirienne, autorité administrative indépendante qui reçoit et analyse les déclarations de soupçon.</li><li><b>PPEF</b> : Pôle pénal économique et financier, qui poursuit et juge les infractions économiques complexes.</li><li>Les <b>assujettis</b> : institutions financières et EPNFD (notaires, avocats, agents immobiliers, casinos, négociants en métaux précieux…).</li></ul>"},
  {"t": "Actualité : la Côte d'Ivoire et la liste grise du GAFI", "h": "<p>La Côte d'Ivoire a été placée sous <b>surveillance renforcée (« liste grise »)</b> du GAFI le <b>25 octobre 2024</b>, après l'évaluation mutuelle conduite de juin 2022 à juin 2023.</p><p>Après 24 mois de réformes, elle en a été <b>officiellement retirée le 30 octobre 2026</b>, à l'issue de la plénière du GAFI à Paris, en même temps que la RDC, Monaco et la Bulgarie.</p><p>Leçon pour le compliance officer : la sortie de la liste grise est un appel à maintenir l'effort. Les banques correspondantes regardent l'efficacité réelle des dispositifs, pas seulement les textes.</p>"}],
 "key": ["Placement → Empilement → Intégration", "Loi uniforme UMOA du 31 mars 2023 ; ordonnance CI n°2023-875 du 23 novembre 2023", "Blanchiment autonome introduit en 2023", "CI : liste grise du 25/10/2024 au 30/10/2026"],
 "quiz": [
  Q("Quelle est la bonne succession des étapes du blanchiment ?", ["Intégration, placement, empilement", "Placement, empilement, intégration", "Empilement, placement, intégration", "Placement, intégration, empilement"], 1, "On place les fonds, on empile les opérations pour brouiller la piste, puis on les intègre dans l'économie légale."),
  Q("Quel texte transpose en Côte d'Ivoire la loi uniforme LBC/FT/FP de 2023 ?", ["La loi n°2016-992", "L'ordonnance n°2023-875 du 23 novembre 2023", "L'ordonnance n°2013-660", "La loi n°2013-450"], 1, "L'ordonnance 2023-875, ratifiée en 2024, abroge la loi 2016-992."),
  Q("Qu'est-ce que le « blanchiment autonome » ?", ["Un blanchiment réalisé par une seule personne", "La possibilité de poursuivre le blanchiment sans devoir d'abord établir l'infraction d'origine", "Le blanchiment par cryptoactifs", "L'auto-blanchiment d'une entreprise"], 1, "Introduit par l'ordonnance 2023-875, il facilite les poursuites contre le blanchiment lui-même."),
  Q("Quand la Côte d'Ivoire a-t-elle été retirée de la liste grise du GAFI ?", ["Juin 2025", "Février 2026", "30 octobre 2026", "Elle y figure toujours"], 2, "Retrait officiel le 30 octobre 2026, après une inscription le 25 octobre 2024."),
  Q("Quel organisme régional de type GAFI couvre l'Afrique de l'Ouest ?", ["GABAC", "GIABA", "MONEYVAL", "ESAAMLG"], 1, "Le GIABA couvre la CEDEAO ; le GABAC couvre l'Afrique centrale."),
  Q("Quelle instruction BCEAO de 2025 porte sur l'identification et la connaissance de la clientèle ?", ["001-03-2025", "002-03-2025", "003-03-2025", "007-09-2017"], 2, "L'instruction 003-03-2025 est consacrée au KYC ; la 001 à l'organisation et au contrôle interne LBC/FT/FP."),
  Q("Dans le financement du terrorisme, l'origine des fonds :", ["Est toujours criminelle", "Peut être parfaitement licite", "Est toujours en espèces", "Est toujours étrangère"], 1, "Le FT peut reposer sur des fonds licites : c'est la destination qui est criminelle.")]})

M.append({"id": "kyc", "t": "KYC et vigilance à l'égard de la clientèle", "ic": "🪪", "lvl": "Intermédiaire",
 "intro": "Identifier, vérifier, connaître : le cœur du dispositif de prévention.",
 "lessons": [
  {"t": "Identifier et vérifier", "h": "<p>Avant d'entrer en relation, l'établissement <b>identifie</b> le client (personne physique ou morale), <b>vérifie</b> son identité sur la base de documents fiables et indépendants, identifie le <b>bénéficiaire effectif</b> et comprend l'<b>objet et la nature</b> de la relation d'affaires.</p><p>Pour une personne morale : statuts, RCCM, pouvoirs des signataires, structure de propriété et de contrôle, bénéficiaires effectifs.</p><p>Le cadre précis est fixé dans l'UMOA par l'<b>instruction BCEAO n°003-03-2025</b> du 18 mars 2025.</p>"},
  {"t": "Le bénéficiaire effectif", "h": "<p>C'est la ou les <b>personnes physiques</b> qui, in fine, possèdent ou contrôlent le client, ou pour le compte desquelles l'opération est effectuée. On le recherche à travers les chaînes de sociétés, les fiducies, les prête-noms.</p><p>Bon réflexe : si la structure est complexe sans raison économique apparente, c'est un signal d'alerte en soi. On ne s'arrête jamais à une société : on remonte jusqu'à des personnes physiques.</p>"},
  {"t": "Vigilance simplifiée, normale, renforcée", "h": "<ul><li><b>Simplifiée</b> : risque faible démontré et documenté (jamais en cas de soupçon).</li><li><b>Normale</b> : la règle.</li><li><b>Renforcée</b> : risque élevé. Exemples : <b>PPE</b> (personnes politiquement exposées), pays à haut risque désignés par le GAFI, relations à distance, montages complexes, correspondance bancaire transfrontalière, produits favorisant l'anonymat.</li></ul><p>La vigilance renforcée implique : approbation par un niveau hiérarchique élevé, recherche de l'origine des fonds et du patrimoine, surveillance accrue des opérations.</p>"},
  {"t": "Les PPE et la vigilance constante", "h": "<p>Une <b>PPE</b> exerce ou a exercé une fonction publique importante (chef d'État, ministre, parlementaire, haut magistrat, dirigeant d'entreprise publique, haut gradé…), ainsi que les membres de sa famille et ses proches associés. La loi uniforme de 2023 a précisé le régime des PPE nationales.</p><p>Le KYC n'est pas un acte unique : la <b>vigilance constante</b> impose de mettre à jour le dossier selon le niveau de risque et de vérifier la cohérence des opérations avec le profil.</p><p>Si l'établissement ne peut pas appliquer les mesures de vigilance, il ne doit pas ouvrir le compte ni exécuter l'opération, doit mettre fin à la relation existante, et envisager une déclaration de soupçon à la CENTIF.</p>"}],
 "key": ["Identifier + vérifier + bénéficiaire effectif + objet de la relation", "Bénéficiaire effectif = toujours une personne physique", "PPE, pays à haut risque, montages complexes → vigilance renforcée", "Impossible d'appliquer la vigilance → pas de relation + DOS à envisager"],
 "quiz": [
  Q("Le bénéficiaire effectif est toujours :", ["Une société", "Une personne physique", "Le signataire du compte", "Le directeur général"], 1, "On remonte les chaînes de détention jusqu'aux personnes physiques qui possèdent ou contrôlent in fine."),
  Q("Un ministre en exercice qui ouvre un compte relève :", ["De la vigilance simplifiée", "De la vigilance normale", "De la vigilance renforcée (PPE)", "D'aucune vigilance particulière"], 2, "Les PPE imposent une vigilance renforcée : approbation hiérarchique, origine des fonds et du patrimoine, suivi accru."),
  Q("Que faire si le client refuse de fournir les justificatifs d'identité requis ?", ["Ouvrir le compte et relancer plus tard", "Ne pas entrer en relation et envisager une déclaration de soupçon", "Ouvrir un compte sans carte", "Demander l'accord du commercial"], 1, "L'impossibilité d'appliquer la vigilance interdit la relation et doit faire envisager une DOS."),
  Q("Quel élément fait partie du KYC d'une personne morale ?", ["La couleur du logo", "La structure de propriété et les bénéficiaires effectifs", "Le chiffre d'affaires de ses concurrents", "La note de crédit de l'État"], 1, "Statuts, RCCM, pouvoirs, structure de propriété et bénéficiaires effectifs sont indispensables."),
  Q("La vigilance simplifiée est possible :", ["Dès qu'un client est connu du directeur", "Uniquement si le risque faible est démontré et en l'absence de soupçon", "Pour toutes les PPE nationales", "Pour tous les clients étrangers"], 1, "Elle exige un risque faible documenté et n'est jamais possible en cas de soupçon."),
  Q("La vigilance constante signifie :", ["Vérifier l'identité une seule fois à l'ouverture", "Mettre à jour le dossier et surveiller la cohérence des opérations tout au long de la relation", "Appeler le client chaque jour", "Bloquer tous les virements"], 1, "Le KYC vit tout au long de la relation, avec une fréquence de mise à jour liée au risque.")]})

M.append({"id": "rba", "t": "L'approche fondée sur les risques", "ic": "🎯", "lvl": "Avancé",
 "intro": "Concentrer les moyens là où le risque est le plus élevé : le principe directeur du GAFI.",
 "lessons": [
  {"t": "Principe", "h": "<p>La <b>Recommandation 1 du GAFI</b> impose aux pays et aux assujettis d'identifier, d'évaluer et de comprendre leurs risques, puis d'appliquer des mesures <b>proportionnées</b>. En 2025, le GAFI a renforcé cette recommandation pour mieux concilier lutte contre le blanchiment et <b>inclusion financière</b> : des mesures simplifiées sont attendues là où le risque est faible.</p><p>Au niveau national, l'<b>évaluation nationale des risques</b> (ENR) identifie les menaces et vulnérabilités du pays ; l'établissement doit en tenir compte.</p>"},
  {"t": "La classification des risques", "h": "<p>On évalue le risque selon plusieurs axes :</p><ul><li><b>Clients</b> : nature, activité, PPE, structure.</li><li><b>Produits et services</b> : espèces, monnaie électronique, banque privée, crédit documentaire…</li><li><b>Canaux de distribution</b> : à distance, intermédiaires, agents.</li><li><b>Zones géographiques</b> : pays à haut risque, zones de conflit, centres offshore.</li></ul><p>Chaque client reçoit une note (faible, moyen, élevé) qui détermine la vigilance, la fréquence de révision et les seuils de surveillance.</p>"},
  {"t": "La cartographie des risques de non-conformité", "h": "<p>Démarche type :</p><ol><li>Recenser les activités et processus.</li><li>Identifier les risques bruts (probabilité × impact).</li><li>Évaluer les dispositifs de maîtrise existants.</li><li>En déduire le <b>risque résiduel</b>.</li><li>Définir des plans d'action priorisés, avec responsables et échéances.</li><li>Mettre à jour au moins annuellement et à chaque changement majeur (nouveau produit, nouveau pays, nouvelle réglementation).</li></ol>"}],
 "key": ["R.1 du GAFI : identifier, évaluer, comprendre, proportionner", "Axes : clients, produits, canaux, géographie", "Risque résiduel = risque brut − efficacité des contrôles", "Cartographie mise à jour au moins chaque année"],
 "quiz": [
  Q("Quelle recommandation du GAFI pose l'approche fondée sur les risques ?", ["R.1", "R.10", "R.16", "R.40"], 0, "La Recommandation 1 est le socle de l'approche par les risques ; elle a été renforcée en 2025."),
  Q("Le risque résiduel correspond :", ["Au risque avant tout contrôle", "Au risque qui subsiste après prise en compte des dispositifs de maîtrise", "Au risque de crédit", "Au risque supporté par le client"], 1, "Risque brut moins l'effet des contrôles = risque résiduel, sur lequel portent les plans d'action."),
  Q("Lequel N'est PAS un axe classique de classification du risque LBC/FT ?", ["La zone géographique", "Le canal de distribution", "Le produit", "La couleur de la carte bancaire"], 3, "Les axes sont clients, produits/services, canaux et géographie."),
  Q("Pourquoi le GAFI a-t-il renforcé la R.1 en 2025 ?", ["Pour supprimer la vigilance", "Pour mieux concilier lutte anti-blanchiment et inclusion financière", "Pour interdire les espèces", "Pour créer une monnaie unique"], 1, "Le GAFI veut des mesures proportionnées : simplifiées quand le risque est faible, pour ne pas exclure les populations."),
  Q("À quelle fréquence minimale mettre à jour la cartographie des risques ?", ["Tous les 10 ans", "Au moins une fois par an et à chaque changement majeur", "Jamais", "Seulement après une sanction"], 1, "Une mise à jour annuelle et à chaque nouveau produit, pays ou texte est la bonne pratique.")]})

M.append({"id": "dos", "t": "Surveillance des opérations et déclaration de soupçon", "ic": "🔍", "lvl": "Avancé",
 "intro": "Détecter, analyser, déclarer : transformer une alerte en information utile pour la CENTIF.",
 "lessons": [
  {"t": "La surveillance des opérations", "h": "<p>Les opérations sont surveillées par des <b>scénarios automatisés</b> (montants, fréquences, pays, contreparties) et par la vigilance humaine. Chaque alerte est analysée, documentée et clôturée ou escaladée.</p><p>Exemples de signaux d'alerte : dépôts d'espèces fractionnés juste sous les seuils, comptes « de passage » (entrées et sorties rapides), virements vers des juridictions à haut risque sans justification, activité incohérente avec le profil, refus de justifier l'origine des fonds, intermédiaires inexpliqués.</p>"},
  {"t": "Seuils clés dans l'UMOA", "h": "<ul><li><b>Déclaration automatique des transactions en espèces</b> à la CENTIF : à partir de <b>15 millions de FCFA</b> (seuil fixé par la BCEAO).</li><li><b>Transport physique international d'espèces</b> et d'instruments négociables au porteur, et <b>paiement d'une dette en espèces</b> : seuils fixés à <b>5 millions de FCFA</b> par deux instructions de juillet 2024.</li><li>Conservation des pièces et documents relatifs à l'identité et aux opérations : <b>10 ans</b>.</li><li>Gel des avoirs et autres mesures imposées <b>« sans délai »</b> : délai maximal de <b>24 heures</b> (définition de l'instruction 001-03-2025).</li></ul><p>Ces seuils évoluent : vérifie toujours le texte en vigueur.</p>"},
  {"t": "La déclaration d'opération suspecte (DOS)", "h": "<p>Dès qu'un établissement <b>sait, soupçonne ou a de bonnes raisons de soupçonner</b> que des fonds proviennent d'une infraction ou financent le terrorisme, il adresse une <b>déclaration de soupçon à la CENTIF</b>, y compris pour une opération tentée ou refusée.</p><p>Une bonne DOS : identité complète des parties, description chronologique des faits, montants, comptes, raisons précises du soupçon, pièces jointes. Elle est factuelle, claire et rapide.</p><p><b>Interdiction de divulgation</b> (tipping-off) : on ne prévient jamais le client ni un tiers. La déclaration faite de bonne foi exonère l'établissement et ses agents de toute responsabilité civile, pénale ou professionnelle.</p>"}],
 "key": ["DOS à la CENTIF dès le soupçon, même pour une opération tentée", "Jamais prévenir le client (tipping-off)", "Espèces ≥ 15 M FCFA : déclaration automatique", "Conservation 10 ans ; « sans délai » = 24 h max"],
 "quiz": [
  Q("À qui adresse-t-on une déclaration de soupçon en Côte d'Ivoire ?", ["À la police", "À la CENTIF", "À la Commission bancaire", "Au client"], 1, "La CENTIF est la cellule de renseignement financier qui reçoit et analyse les DOS."),
  Q("Peut-on informer le client qu'une déclaration de soupçon le concerne ?", ["Oui, par transparence", "Oui, s'il le demande", "Non, c'est interdit (tipping-off)", "Seulement après 30 jours"], 2, "L'interdiction de divulgation est absolue : prévenir le client est une infraction."),
  Q("Quel est le seuil de déclaration automatique des transactions en espèces à la CENTIF dans l'UMOA ?", ["1 million FCFA", "5 millions FCFA", "15 millions FCFA", "100 millions FCFA"], 2, "Le seuil est de 15 millions de FCFA."),
  Q("Pendant combien de temps conserver les documents d'identification et d'opérations ?", ["2 ans", "5 ans", "10 ans", "Indéfiniment"], 2, "La durée de conservation est de 10 ans."),
  Q("Une opération refusée parce qu'elle paraît suspecte :", ["Ne donne lieu à aucune déclaration", "Peut et doit faire l'objet d'une DOS", "Doit être signalée au client", "Doit être exécutée quand même"], 1, "La DOS couvre aussi les opérations tentées ou refusées."),
  Q("Dans l'instruction BCEAO 001-03-2025, « sans délai » signifie :", ["Dans la semaine", "Dans un délai maximal de 24 heures", "Dans le mois", "Avant la fin de l'exercice"], 1, "L'instruction définit « sans délai » comme un délai maximal de vingt-quatre heures."),
  Q("Un client dépose chaque jour 14 millions de FCFA en espèces. C'est :", ["Normal", "Un fractionnement possible pour éviter le seuil de 15 millions : signal d'alerte", "Obligatoire", "Interdit par principe"], 1, "Le fractionnement sous les seuils (structuring) est un signal d'alerte classique.")]})

M.append({"id": "sanc", "t": "Sanctions financières internationales et embargos", "ic": "🚫", "lvl": "Avancé",
 "intro": "Filtrer, geler, ne pas mettre de fonds à disposition : la conformité aux régimes de sanctions.",
 "lessons": [
  {"t": "Les régimes de sanctions", "h": "<ul><li><b>ONU</b> : sanctions du Conseil de sécurité (terrorisme, prolifération, pays). Elles s'imposent à tous les États membres. Recommandations 6 et 7 du GAFI : gel <b>sans délai</b>.</li><li><b>États-Unis</b> : OFAC (Office of Foreign Assets Control), liste <b>SDN</b>, sanctions dites secondaires visant les non-Américains. Règle des 50 % : une entité détenue à 50 % ou plus par des personnes sanctionnées est elle-même bloquée.</li><li><b>Union européenne</b> : liste consolidée des sanctions financières.</li><li><b>Royaume-Uni</b> : OFSI.</li><li>Listes <b>nationales</b> (gel administratif des avoirs).</li></ul><p>Une banque ivoirienne qui opère en dollars ou en euros est exposée de fait aux régimes américain et européen à travers ses correspondants.</p>"},
  {"t": "Le filtrage", "h": "<p>On filtre les <b>clients</b> (à l'entrée en relation et à chaque mise à jour des listes) et les <b>opérations</b> (virements, crédits documentaires, parties, navires, ports).</p><p>Gestion d'une alerte : comparer les éléments discriminants (date de naissance, nationalité, adresse, identifiants) pour écarter les <b>homonymes</b>. En cas de correspondance confirmée : <b>geler</b>, ne pas exécuter, déclarer à l'autorité compétente, documenter.</p><p>Indices de contournement : intermédiaires inutiles, changements de dernière minute du bénéficiaire, transbordements, documents incohérents, prix anormaux.</p>"}],
 "key": ["ONU = obligatoire pour tous ; OFAC/UE via les correspondants", "Règle OFAC des 50 %", "Gel sans délai (24 h)", "Filtrer clients ET opérations ; écarter les homonymes par les éléments discriminants"],
 "quiz": [
  Q("Que signifie la règle OFAC des 50 % ?", ["Une amende de 50 %", "Une entité détenue à 50 % ou plus par des personnes sanctionnées est elle-même bloquée", "Seuls 50 % des fonds sont gelés", "Le filtrage porte sur 50 % des opérations"], 1, "Les entités détenues à 50 % ou plus (cumulés) par des SDN sont traitées comme bloquées."),
  Q("Une alerte de filtrage indique un nom identique à une personne sanctionnée. Première étape ?", ["Geler immédiatement sans analyse", "Comparer les éléments discriminants (date de naissance, nationalité…) pour écarter un homonyme", "Prévenir le client", "Ignorer l'alerte"], 1, "On qualifie l'alerte : homonyme ou correspondance avérée. Si confirmée : gel et déclaration."),
  Q("Quelles sanctions s'imposent à tous les États membres des Nations unies ?", ["Celles de l'OFAC", "Celles du Conseil de sécurité de l'ONU", "Celles de l'UE", "Celles du Royaume-Uni"], 1, "Les résolutions du Conseil de sécurité sont obligatoires pour tous les États membres."),
  Q("Pourquoi une banque ivoirienne doit-elle respecter les sanctions américaines ?", ["Elle n'y est jamais tenue", "Parce qu'elle opère en dollars via des correspondants exposés au droit américain", "Parce que la BCEAO est américaine", "Pour obtenir un agrément"], 1, "Les correspondants bancaires et la compensation en dollars exposent de fait aux sanctions de l'OFAC."),
  Q("Lequel est un indice de contournement des sanctions ?", ["Un client salarié qui reçoit son salaire", "Un changement de bénéficiaire de dernière minute vers un intermédiaire sans raison", "Un paiement de facture d'électricité", "Un virement entre deux comptes du même client"], 1, "Les intermédiaires inexpliqués et changements tardifs sont des indices classiques de contournement.")]})

M.append({"id": "corr", "t": "Anticorruption et éthique des affaires", "ic": "⚖️", "lvl": "Intermédiaire",
 "intro": "Prévenir la corruption, les conflits d'intérêts et protéger les lanceurs d'alerte.",
 "lessons": [
  {"t": "Le cadre ivoirien", "h": "<p>L'<b>ordonnance n°2013-660 du 20 septembre 2013</b> relative à la prévention et à la lutte contre la corruption et les infractions assimilées définit notamment la corruption, y compris d'agents publics étrangers, le trafic d'influence, le détournement, l'enrichissement illicite.</p><p>Elle crée la <b>Haute Autorité pour la Bonne Gouvernance (HABG)</b>, chargée notamment de recevoir les <b>déclarations de patrimoine</b> des agents publics assujettis.</p>"},
  {"t": "Les lois à portée internationale", "h": "<ul><li><b>FCPA</b> (États-Unis, 1977) : corruption d'agents publics étrangers et exigences comptables ; portée extraterritoriale large.</li><li><b>UK Bribery Act</b> (2010) : sa <b>section 7</b> crée une infraction d'<b>échec à prévenir la corruption</b> ; la seule défense est d'avoir des procédures adéquates.</li><li><b>Loi Sapin II</b> (France, 2016) : programme anticorruption obligatoire pour les grandes entreprises, contrôlé par l'<b>AFA</b>, autour de <b>8 piliers</b> : code de conduite, dispositif d'alerte interne, cartographie des risques, évaluation des tiers, contrôles comptables, formation, régime disciplinaire, contrôle et évaluation internes.</li><li>Norme <b>ISO 37001</b> : systèmes de management anticorruption.</li></ul>"},
  {"t": "Cadeaux, conflits d'intérêts et alerte", "h": "<ul><li><b>Cadeaux et invitations</b> : politique écrite, seuils, registre, interdiction des espèces et des cadeaux pendant un appel d'offres.</li><li><b>Conflits d'intérêts</b> : déclarer, documenter, se retirer de la décision.</li><li><b>Évaluation des tiers</b> (due diligence) : intermédiaires, agents, fournisseurs, partenaires.</li><li><b>Dispositif d'alerte</b> (whistleblowing) : canal confidentiel, protection contre les représailles, traitement indépendant.</li></ul>"}],
 "key": ["CI : ordonnance n°2013-660 du 20 septembre 2013 ; HABG", "FCPA 1977, UK Bribery Act 2010 (section 7), Sapin II 2016 (AFA, 8 piliers)", "ISO 37001 = management anticorruption", "Alerte : confidentialité et protection contre les représailles"],
 "quiz": [
  Q("Quel texte ivoirien porte sur la prévention et la lutte contre la corruption ?", ["La loi n°2013-450", "L'ordonnance n°2013-660 du 20 septembre 2013", "L'ordonnance n°2023-875", "La loi n°2016-992"], 1, "L'ordonnance 2013-660 et ses modifications ; elle institue la HABG."),
  Q("Quelle institution ivoirienne reçoit les déclarations de patrimoine des agents publics ?", ["La CENTIF", "La HABG", "L'ARTCI", "La BCEAO"], 1, "La Haute Autorité pour la Bonne Gouvernance."),
  Q("La section 7 du UK Bribery Act crée :", ["Une taxe sur les cadeaux", "Une infraction d'échec à prévenir la corruption", "Un registre des PPE", "Une autorité de contrôle"], 1, "L'entreprise est responsable si elle n'a pas de procédures adéquates pour prévenir la corruption."),
  Q("Combien de piliers compte le programme anticorruption de la loi Sapin II ?", ["3", "5", "8", "12"], 2, "Huit piliers, contrôlés par l'Agence française anticorruption (AFA)."),
  Q("Pendant un appel d'offres, un fournisseur candidat offre une montre de valeur à l'acheteur. Que faire ?", ["Accepter discrètement", "Refuser, déclarer à la conformité et documenter", "Accepter si la valeur est inférieure au salaire", "Accepter puis revendre"], 1, "Les cadeaux pendant une procédure d'achat sont à proscrire ; on déclare et on documente."),
  Q("Quelle norme ISO encadre les systèmes de management anticorruption ?", ["ISO 9001", "ISO 27001", "ISO 37001", "ISO 14001"], 2, "ISO 37001 pour l'anticorruption ; ISO 37301 pour les systèmes de management de la conformité.")]})

M.append({"id": "data", "t": "Protection des données personnelles", "ic": "🔐", "lvl": "Intermédiaire",
 "intro": "Concilier KYC et respect de la vie privée.",
 "lessons": [
  {"t": "Le cadre ivoirien", "h": "<p>La <b>loi n°2013-450 du 19 juin 2013</b> relative à la protection des données à caractère personnel encadre la collecte, le traitement, la conservation et la diffusion des données. Elle désigne l'<b>ARTCI</b> (Autorité de Régulation des Télécommunications/TIC de Côte d'Ivoire) comme autorité de protection.</p><p>Elle distingue les <b>données sensibles</b>, soumises à un régime renforcé, et prévoit des formalités préalables auprès de l'autorité ainsi que des sanctions en cas de manquement.</p>"},
  {"t": "Le RGPD européen", "h": "<p>Le <b>règlement (UE) 2016/679</b> (RGPD), applicable depuis le 25 mai 2018, s'applique aussi aux organismes hors UE qui ciblent des personnes situées dans l'UE. Amendes jusqu'à <b>20 millions d'euros ou 4 % du chiffre d'affaires mondial</b>.</p><p>Principes : licéité, loyauté et transparence ; limitation des finalités ; minimisation ; exactitude ; limitation de la conservation ; intégrité et confidentialité ; responsabilité (accountability).</p>"},
  {"t": "KYC et données : trouver l'équilibre", "h": "<ul><li>La LBC/FT est une <b>base légale</b> de traitement : le client ne peut pas s'y opposer, mais il doit être informé.</li><li>Ne collecter que ce qui est nécessaire.</li><li>Respecter les durées de conservation (10 ans pour la LBC/FT), puis supprimer ou archiver.</li><li>Encadrer les transferts hors du pays (groupes bancaires, prestataires cloud).</li><li>Sécuriser les accès : besoin d'en connaître.</li></ul>"}],
 "key": ["CI : loi n°2013-450 du 19 juin 2013 ; autorité = ARTCI", "RGPD : 20 M€ ou 4 % du CA mondial", "Minimisation, finalité, durée de conservation", "La LBC/FT est une base légale de traitement"],
 "quiz": [
  Q("Quelle autorité ivoirienne est chargée de la protection des données personnelles ?", ["La HABG", "L'ARTCI", "La CENTIF", "La Commission bancaire"], 1, "La loi 2013-450 désigne l'ARTCI comme autorité de protection."),
  Q("Quelle est l'amende maximale prévue par le RGPD ?", ["1 million d'euros", "20 millions d'euros ou 4 % du chiffre d'affaires mondial", "1 % du chiffre d'affaires", "Aucune amende"], 1, "Le montant le plus élevé des deux est retenu pour les manquements les plus graves."),
  Q("Le principe de minimisation signifie :", ["Collecter toutes les données possibles", "Ne collecter que les données nécessaires à la finalité", "Réduire la taille des fichiers", "Supprimer les données après un mois"], 1, "On ne collecte que ce qui est adéquat, pertinent et limité à la finalité."),
  Q("Un client demande la suppression de son dossier KYC 2 ans après la clôture de son compte. Que répondre ?", ["Supprimer immédiatement", "Expliquer que la loi impose une conservation de 10 ans pour la LBC/FT", "Refuser sans explication", "Transférer le dossier au client"], 1, "L'obligation légale de conservation prévaut ; on informe le client de la durée et de la finalité.")]})

M.append({"id": "mkt", "t": "Marchés, protection de la clientèle et conduite", "ic": "📈", "lvl": "Intermédiaire",
 "intro": "Intégrité des marchés, traitement des réclamations et loyauté envers les clients.",
 "lessons": [
  {"t": "Intégrité des marchés", "h": "<p>Les <b>abus de marché</b> regroupent l'utilisation d'une <b>information privilégiée</b> (délit d'initié), la divulgation illicite de cette information et la <b>manipulation de cours</b>. Sur le marché financier régional de l'UMOA, c'est l'<b>AMF-UMOA</b> qui veille à l'intégrité du marché (BRVM).</p><p>Outils de conformité : listes d'initiés, listes de surveillance et d'interdiction, murailles de Chine, déclaration des transactions personnelles des collaborateurs, détection des opérations suspectes.</p>"},
  {"t": "Protection de la clientèle", "h": "<ul><li><b>Transparence</b> des conditions et tarifs.</li><li><b>Devoir de conseil</b> et adéquation du produit au client.</li><li>Traitement des <b>réclamations</b> : la circulaire n°002-2020/CB/C de la Commission bancaire encadre le traitement des réclamations des clients des établissements assujettis ; le client peut aussi saisir la Commission bancaire.</li><li>Lutte contre le surendettement et les pratiques commerciales trompeuses.</li></ul>"},
  {"t": "Conduite et culture", "h": "<p>La conformité moderne va au-delà des règles : on parle de <b>risque de conduite</b> (conduct risk), c'est-à-dire de comportements qui nuisent aux clients ou au marché. Le ton donné par la direction (<b>tone at the top</b>), les incitations commerciales, la formation et les sanctions internes façonnent la culture.</p>"}],
 "key": ["Abus de marché : initié, divulgation illicite, manipulation", "AMF-UMOA veille à l'intégrité du marché régional", "Réclamations : circulaire n°002-2020/CB/C", "Tone at the top et incitations"],
 "quiz": [
  Q("Lequel est un abus de marché ?", ["Acheter des actions après la publication des résultats", "Acheter des actions en connaissant à l'avance une fusion non publique", "Investir dans un OPCVM", "Vendre à perte"], 1, "Utiliser une information privilégiée non publique est un délit d'initié."),
  Q("Quel texte de la Commission bancaire encadre le traitement des réclamations des clients ?", ["Circulaire 05-2017/CB/C", "Circulaire 002-2020/CB/C", "Instruction 003-03-2025", "Ordonnance 2013-660"], 1, "La circulaire n°002-2020/CB/C porte sur le traitement des réclamations."),
  Q("Une « muraille de Chine » sert à :", ["Protéger les locaux", "Cloisonner les informations privilégiées entre services", "Filtrer les sanctions", "Stocker les archives"], 1, "Elle empêche la circulation d'informations privilégiées entre équipes (conseil, marché…)."),
  Q("Le « tone at the top » désigne :", ["Le volume sonore des réunions", "L'exemple et le message donnés par la direction en matière d'éthique", "Le classement des banques", "La hiérarchie des normes"], 1, "La culture de conformité se construit d'abord par l'exemplarité des dirigeants.")]})

M.append({"id": "gov", "t": "Contrôle interne, gouvernance et reporting", "ic": "📋", "lvl": "Avancé",
 "intro": "Organiser, contrôler, mesurer et rendre compte.",
 "lessons": [
  {"t": "Gouvernance du dispositif LBC/FT/FP", "h": "<p>Selon l'<b>instruction BCEAO n°001-03-2025</b> :</p><ul><li>L'<b>organe délibérant</b> définit la stratégie LBC/FT/FP et en surveille la mise en œuvre.</li><li>L'<b>organe exécutif</b> met en place l'organisation, les procédures et les moyens.</li><li>La <b>structure interne LBC/FT/FP</b> doit pouvoir accéder <b>directement à l'organe délibérant</b> en cas de besoin.</li><li>La formation du personnel est une obligation précisée par le texte.</li></ul>"},
  {"t": "Le plan de contrôle", "h": "<p>Le compliance officer construit un <b>plan de contrôle permanent</b> annuel fondé sur la cartographie : contrôles sur échantillon des dossiers KYC, revue des alertes clôturées, tests du filtrage, revue des DOS, suivi des formations, contrôle des nouveaux produits.</p><p>Chaque contrôle a un objectif, une méthode, un échantillon, une fréquence, un responsable et un livrable. Les anomalies alimentent des <b>plans d'action</b> suivis jusqu'à leur clôture.</p>"},
  {"t": "Indicateurs et reporting", "h": "<ul><li><b>KRI</b> : taux de dossiers KYC incomplets, délai de traitement des alertes, nombre de DOS, taux de formation, alertes de filtrage en attente, recommandations en retard.</li><li><b>Tableau de bord</b> mensuel à la direction, rapport périodique au comité des risques ou d'audit et à l'organe délibérant.</li><li><b>Rapports réglementaires</b> au superviseur selon les textes en vigueur.</li></ul><p>Un bon rapport : synthèse des risques, faits marquants, incidents, indicateurs, avancement des plans d'action, besoins en ressources.</p>"}],
 "key": ["Instruction 001-03-2025 : rôles des organes délibérant et exécutif", "Accès direct du responsable LBC/FT à l'organe délibérant", "Plan de contrôle fondé sur la cartographie", "KRI + reporting régulier"],
 "quiz": [
  Q("Qui définit la stratégie LBC/FT/FP d'une institution financière selon l'instruction 001-03-2025 ?", ["Le responsable conformité seul", "L'organe délibérant", "La CENTIF", "Les clients"], 1, "L'organe délibérant définit la stratégie ; l'organe exécutif la met en œuvre."),
  Q("Le responsable de la structure LBC/FT/FP doit pouvoir :", ["Accéder directement à l'organe délibérant en cas de besoin", "Valider les crédits", "Fixer les taux d'intérêt", "Recruter les commerciaux"], 0, "Cet accès direct garantit son indépendance."),
  Q("Lequel est un bon indicateur de risque (KRI) de conformité ?", ["Le cours de bourse", "Le taux de dossiers KYC incomplets", "Le nombre d'agences", "Le chiffre d'affaires"], 1, "Il mesure directement la qualité du dispositif de connaissance client."),
  Q("Sur quoi doit reposer le plan de contrôle permanent ?", ["Sur les préférences du directeur", "Sur la cartographie des risques", "Sur le hasard", "Sur le budget marketing"], 1, "On contrôle en priorité là où le risque résiduel est le plus élevé.")]})

M.append({"id": "intl", "t": "Tendances internationales et nouvelles technologies", "ic": "🌐", "lvl": "Expert",
 "intro": "GAFI, Union européenne, cryptoactifs, RegTech : ce qui change pour la profession.",
 "lessons": [
  {"t": "GAFI : les évolutions récentes", "h": "<ul><li><b>Recommandation 16 révisée le 18 juin 2025</b>, rebaptisée « Payment transparency » : elle couvre les paiements transfrontaliers au sens large et étend certaines obligations aux virements domestiques. Les institutions financières devront s'y conformer d'ici <b>2030</b>. Pour les paiements transfrontaliers de pair à pair au-delà de 1 000 USD/EUR, le nom, l'adresse et la date de naissance doivent accompagner le paiement.</li><li><b>Recommandation 1</b> renforcée en 2025 (approche par les risques et inclusion financière).</li><li><b>Recommandation 15</b> : actifs virtuels et prestataires de services d'actifs virtuels (PSAV), avec la « travel rule ».</li><li>Listes du GAFI : la « liste noire » (appel à l'action) vise la Corée du Nord, l'Iran et le Myanmar.</li></ul>"},
  {"t": "Union européenne : le paquet anti-blanchiment", "h": "<ul><li><b>AMLA</b>, autorité européenne de lutte contre le blanchiment, créée par le règlement (UE) 2024/1620, opérationnelle à <b>Francfort depuis juillet 2025</b>.</li><li><b>AMLR</b>, règlement (UE) 2024/1624 : règlement unique directement applicable à partir du <b>10 juillet 2027</b>.</li><li>À partir de <b>2028</b>, l'AMLA supervisera directement jusqu'à <b>40</b> entités financières transfrontalières à risque élevé.</li></ul><p>Pour une banque ivoirienne filiale d'un groupe européen, ces règles s'appliqueront par la politique du groupe.</p>"},
  {"t": "Cryptoactifs, RegTech et IA", "h": "<ul><li><b>PSAV</b> : la loi uniforme de 2023 en fait des assujettis LBC/FT/FP.</li><li><b>RegTech</b> : vérification d'identité numérique, filtrage intelligent, surveillance par apprentissage automatique, analyse des réseaux.</li><li><b>IA</b> : gain d'efficacité, mais exigence d'explicabilité, de gouvernance des modèles et de maîtrise des biais.</li><li><b>ISO 37301:2021</b> : norme internationale des systèmes de management de la conformité, certifiable.</li></ul>"}],
 "key": ["R.16 « Payment transparency » révisée en juin 2025, conformité d'ici 2030", "AMLA à Francfort (2025) ; AMLR applicable le 10 juillet 2027", "Liste noire du GAFI : Corée du Nord, Iran, Myanmar", "ISO 37301:2021 = management de la conformité"],
 "quiz": [
  Q("Quel est le nouveau titre de la Recommandation 16 du GAFI révisée en juin 2025 ?", ["Customer due diligence", "Payment transparency", "Virtual assets", "Beneficial ownership"], 1, "La R.16 est devenue « Payment transparency » et couvre plus largement les paiements."),
  Q("Où siège l'autorité européenne de lutte contre le blanchiment (AMLA) ?", ["Bruxelles", "Paris", "Francfort", "Luxembourg"], 2, "L'AMLA est opérationnelle à Francfort depuis juillet 2025."),
  Q("À partir de quand le règlement européen AMLR s'applique-t-il ?", ["1er janvier 2025", "10 juillet 2027", "2030", "Il est déjà abrogé"], 1, "L'AMLR (UE) 2024/1624 s'applique à partir du 10 juillet 2027."),
  Q("Quels pays figurent sur la « liste noire » du GAFI ?", ["Côte d'Ivoire, Cameroun, Kenya", "Corée du Nord, Iran, Myanmar", "Algérie, Namibie, Maroc", "Aucun pays"], 1, "Les juridictions faisant l'objet d'un appel à l'action sont la Corée du Nord, l'Iran et le Myanmar."),
  Q("Quelle norme ISO porte sur les systèmes de management de la conformité ?", ["ISO 37301", "ISO 9001", "ISO 31000", "ISO 22301"], 0, "ISO 37301:2021, certifiable ; ISO 31000 porte sur le management du risque."),
  Q("D'ici quand les institutions financières devront-elles appliquer la R.16 révisée ?", ["2026", "2028", "2030", "2035"], 2, "Le GAFI a fixé un horizon de mise en œuvre à 2030.")]})

M.append({"id": "car", "t": "Le métier et la carrière de compliance officer", "ic": "🎓", "lvl": "Tous niveaux",
 "intro": "Missions concrètes, compétences, certifications et posture pour devenir un expert reconnu.",
 "lessons": [
  {"t": "Une journée type", "h": "<ul><li>Revue des alertes de surveillance et de filtrage.</li><li>Avis de conformité sur une entrée en relation à risque ou un nouveau produit.</li><li>Échanges avec les métiers : pédagogie et solutions, pas seulement des refus.</li><li>Veille réglementaire et mise à jour des procédures.</li><li>Préparation d'un reporting ou d'une mission du superviseur.</li><li>Formation des équipes.</li></ul>"},
  {"t": "Compétences et posture", "h": "<p><b>Savoirs</b> : réglementation bancaire et LBC/FT/FP, droit pénal des affaires, risques, contrôle interne, data.</p><p><b>Savoir-faire</b> : analyse, rédaction claire, investigation, gestion de projet, maîtrise des outils.</p><p><b>Savoir-être</b> : intégrité, courage, diplomatie, esprit critique, discrétion absolue, sens du business. Le meilleur compliance officer est celui que les métiers viennent consulter <i>avant</i> d'agir.</p>"},
  {"t": "Certifications reconnues", "h": "<ul><li><b>CAMS</b> (ACAMS) : référence mondiale en anti-blanchiment.</li><li><b>CFE</b> (ACFE) : examinateur certifié en fraude.</li><li><b>Diplômes de l'ICA</b> (International Compliance Association) : conformité, LBC, sanctions.</li><li><b>CCEP</b> (SCCE) : éthique et conformité.</li><li>Formations des écoles bancaires et universitaires de la sous-région, et programmes de formation proposés par les autorités et associations professionnelles.</li></ul><p>Vérifie les conditions et tarifs à jour directement auprès de chaque organisme.</p>"}],
 "key": ["2e ligne : conseiller, contrôler, former, rendre compte", "Posture : être consulté avant l'action", "CAMS, CFE, ICA, CCEP", "Intégrité et discrétion absolues"],
 "quiz": [
  Q("Quelle certification est la référence mondiale en anti-blanchiment ?", ["PMP", "CAMS", "CFA", "ITIL"], 1, "La CAMS, délivrée par l'ACAMS."),
  Q("Quelle posture est attendue d'un bon compliance officer ?", ["Dire non à tout", "Être consulté en amont et proposer des solutions conformes", "Laisser faire les métiers", "Ne jamais rédiger"], 1, "La conformité crée de la valeur en sécurisant les projets dès leur conception."),
  Q("Que délivre l'ACFE ?", ["La CAMS", "La CFE (examinateur certifié en fraude)", "Le RGPD", "La licence bancaire"], 1, "L'Association of Certified Fraud Examiners délivre la CFE.")]})

